#!/bin/bash
set -euo pipefail

PROJECT_DIR="$(cd "$(dirname "$0")/.." && pwd)"
BUILD_DIR="$PROJECT_DIR/.build/widget"
SECRET_FILE="$PROJECT_DIR/Sources/ClashVergeWidgetCore/GeneratedBridgeSecret.swift"
APP="$PROJECT_DIR/dist/Clash Verge Widget.app"
APPEX="$APP/Contents/PlugIns/ClashVergeWidgetExtension.appex"
SDK="$(xcrun --sdk macosx --show-sdk-path)"
ARCH="$(uname -m)"

restore_secret_source() {
    printf '%s\n' \
        '// Regenerated by Scripts/build.sh for each installed build.' \
        'public enum GeneratedBridgeSecret {' \
        '    public static let token = "development-placeholder-regenerated-by-build"' \
        '}' > "$SECRET_FILE"
    chmod 644 "$SECRET_FILE"
}
trap restore_secret_source EXIT

cd "$PROJECT_DIR"
mkdir -p "$BUILD_DIR"
BRIDGE_TOKEN="$(uuidgen | tr -d '-' | tr '[:upper:]' '[:lower:]')"
SECRET_TEMP="$(mktemp "$BUILD_DIR/GeneratedBridgeSecret.XXXXXX")"
printf '%s\n' \
    '// Regenerated by Scripts/build.sh for each installed build.' \
    'public enum GeneratedBridgeSecret {' \
    "    public static let token = \"$BRIDGE_TOKEN\"" \
    '}' > "$SECRET_TEMP"
mv "$SECRET_TEMP" "$SECRET_FILE"
chmod 600 "$SECRET_FILE"

swift test
swift build -c release --product ClashVergeWidgetHost
HOST_BIN_DIR="$(swift build -c release --show-bin-path)"

rm -rf "$PROJECT_DIR/dist"
mkdir -p "$APP/Contents/MacOS" "$APP/Contents/Resources" \
    "$APPEX/Contents/MacOS" "$APPEX/Contents/Resources"

cp "$HOST_BIN_DIR/ClashVergeWidgetHost" "$APP/Contents/MacOS/ClashVergeWidgetHost"
cp "$PROJECT_DIR/Resources/Host-Info.plist" "$APP/Contents/Info.plist"
cp "$PROJECT_DIR/Resources/Widget-Info.plist" "$APPEX/Contents/Info.plist"

WIDGET_SOURCES=(
    "$PROJECT_DIR/Sources/ClashVergeWidgetCore/GeneratedBridgeSecret.swift"
    "$PROJECT_DIR/Sources/ClashVergeWidgetCore/BridgeContract.swift"
    "$PROJECT_DIR/Sources/ClashVergeWidgetExtension/BridgeClient.swift"
    "$PROJECT_DIR/Sources/ClashVergeWidgetExtension/StatusProvider.swift"
    "$PROJECT_DIR/Sources/ClashVergeWidgetExtension/WidgetView.swift"
    "$PROJECT_DIR/Sources/ClashVergeWidgetExtension/ClashVergeWidget.swift"
)

xcrun swiftc \
    -parse-as-library \
    -application-extension \
    -O \
    -whole-module-optimization \
    -swift-version 6 \
    -warnings-as-errors \
    -module-name ClashVergeWidgetExtension \
    -target "$ARCH-apple-macos14.0" \
    -sdk "$SDK" \
    -framework Foundation \
    -framework SwiftUI \
    -framework WidgetKit \
    "${WIDGET_SOURCES[@]}" \
    -o "$APPEX/Contents/MacOS/ClashVergeWidgetExtension"

plutil -lint "$APP/Contents/Info.plist" "$APPEX/Contents/Info.plist"
codesign --force --sign - \
    --requirements '=designated => identifier "com.local.ClashVergeWidget.Extension"' \
    --entitlements "$PROJECT_DIR/Resources/Widget.entitlements" \
    "$APPEX"
codesign --force --sign - \
    --requirements '=designated => identifier "com.local.ClashVergeWidget"' \
    "$APP"
codesign --verify --deep --strict --verbose=2 "$APP"

echo "$APP"
